#include <iostream>
#include <vector>
#include <string>
#include <cstring>
#include <csignal>
#include <atomic>
#include <thread>
#include <mutex>
#include <chrono>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>

static std::atomic<bool> g_shutdown_requested{false};
static std::mutex g_session_mutex;

struct ContainerSession {
    std::string container_id;
    std::vector<unsigned char> session_key;
    std::vector<unsigned char> auth_token_enc;
    std::vector<unsigned char> auth_token_iv;
    bool authenticated;
};

static std::vector<ContainerSession> g_sessions;

void signal_handler(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_shutdown_requested.store(true);
    }
}

enum class DecryptResult {
    SUCCESS,
    PADDING_ERROR,
    DECRYPTION_FAILED,
    INVALID_LENGTH
};

DecryptResult decrypt_and_verify(const std::vector<unsigned char>& ciphertext,
                                  const std::vector<unsigned char>& key,
                                  const std::vector<unsigned char>& iv,
                                  std::vector<unsigned char>& plaintext) {
    if (ciphertext.size() % 16 != 0 || ciphertext.empty()) {
        return DecryptResult::INVALID_LENGTH;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return DecryptResult::DECRYPTION_FAILED;

    EVP_CIPHER_CTX_set_padding(ctx, 0);  // manual padding check

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key.data(), iv.data()) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return DecryptResult::DECRYPTION_FAILED;
    }

    plaintext.resize(ciphertext.size());
    int out_len = 0;

    if (EVP_DecryptUpdate(ctx, plaintext.data(), &out_len, ciphertext.data(), ciphertext.size()) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return DecryptResult::DECRYPTION_FAILED;
    }

    int final_len = 0;
    EVP_DecryptFinal_ex(ctx, plaintext.data() + out_len, &final_len);
    EVP_CIPHER_CTX_free(ctx);

    out_len += final_len;
    plaintext.resize(out_len);

    // PKCS7 padding validation
    unsigned char pad_byte = plaintext.back();
    if (pad_byte == 0 || pad_byte > 16) {
        return DecryptResult::PADDING_ERROR;
    }

    for (int i = 0; i < pad_byte; i++) {
        if (plaintext[plaintext.size() - 1 - i] != pad_byte) {
            return DecryptResult::PADDING_ERROR;
        }
    }

    plaintext.resize(plaintext.size() - pad_byte);
    return DecryptResult::SUCCESS;
}

std::string handle_auth_request(const std::vector<unsigned char>& encrypted_token,
                                 const std::vector<unsigned char>& iv,
                                 const std::string& container_id) {
    std::lock_guard<std::mutex> lock(g_session_mutex);

    for (auto& session : g_sessions) {
        if (session.container_id == container_id) {
            std::vector<unsigned char> plaintext;
            DecryptResult result = decrypt_and_verify(encrypted_token, session.session_key, iv, plaintext);

            switch (result) {
                case DecryptResult::SUCCESS:
                    session.authenticated = true;
                    return "{\"status\": \"authenticated\", \"code\": 200}";
                case DecryptResult::PADDING_ERROR:
                    return "{\"status\": \"error\", \"code\": 400, \"detail\": \"malformed token\"}";
                case DecryptResult::INVALID_LENGTH:
                    return "{\"status\": \"error\", \"code\": 422, \"detail\": \"invalid length\"}";
                case DecryptResult::DECRYPTION_FAILED:
                    return "{\"status\": \"error\", \"code\": 500, \"detail\": \"internal error\"}";
            }
        }
    }
    return "{\"status\": \"error\", \"code\": 404, \"detail\": \"session not found\"}";
}

void graceful_shutdown_drain() {
    std::lock_guard<std::mutex> lock(g_session_mutex);
    for (auto& session : g_sessions) {
        if (session.authenticated) {
            std::cout << "[shutdown] draining container: " << session.container_id << std::endl;
        }
    }
    g_sessions.clear();
}

void orchestrator_loop(int server_fd) {
    while (!g_shutdown_requested.load()) {
        struct sockaddr_in client_addr;
        socklen_t addr_len = sizeof(client_addr);

        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(server_fd, &readfds);
        struct timeval tv = {1, 0};

        int sel = select(server_fd + 1, &readfds, nullptr, nullptr, &tv);
        if (sel <= 0) continue;

        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &addr_len);
        if (client_fd < 0) continue;

        unsigned char buf[4096];
        ssize_t n = recv(client_fd, buf, sizeof(buf), 0);
        if (n > 48) {
            std::string container_id(buf, buf + 32);
            std::vector<unsigned char> iv(buf + 32, buf + 48);
            std::vector<unsigned char> token(buf + 48, buf + n);

            std::string response = handle_auth_request(token, iv, container_id);
            send(client_fd, response.c_str(), response.size(), 0);
        }
        close(client_fd);
    }
    graceful_shutdown_drain();
}

int main() {
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    // Pre-register a test session
    ContainerSession test_session;
    test_session.container_id = std::string(32, 'A');
    test_session.session_key.resize(32);
    RAND_bytes(test_session.session_key.data(), 32);
    test_session.authenticated = false;
    g_sessions.push_back(test_session);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(8443);
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 16);

    std::cout << "[orchestrator] listening on port 8443" << std::endl;
    orchestrator_loop(server_fd);
    close(server_fd);
    return 0;
}
